const items = $input.all();
if (items.length === 0) return [];
return items.slice(0, 10);

const pages = $input.all();
const hotels = $('Limit Batch').all();
const out = [];

const keywords = ['kontakt', 'contact', 'about', 'company', 'team', 'staff', 'management', 'jobs', 'career', 'karriere', 'bewerbung', 'personal', 'hr', 'restaurant', 'kitchen', 'fnb', 'gastronomie', 'chef', 'impressum', 'datenschutz', 'legal', 'ueber-uns', 'über-uns'];
const emailRegex = /([a-zA-Z0-9._-]+(?:@|\(at\)|\[at\]|&#64;|&amp;#64;|\{at\})[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/gi;

function extractEmails(html) {
  const raw = html.match(emailRegex) || [];
  return [...new Set(raw.map(e => e.toLowerCase()))];
}

for (let i = 0; i < hotels.length; i++) {
  const hotel = hotels[i].json;
  const html = pages[i]?.json?.data || '';
  const base_url = hotel.website || '';

  const homepageEmails = extractEmails(html);

  const linkRegex = /href=["']([^"']+)["']/gi;
  let match;
  const links = [];
  const socials = [];

  while ((match = linkRegex.exec(html)) !== null) {
    let l = match[1].trim();
    if (l.startsWith('mailto:') || l.startsWith('tel:') || l.startsWith('javascript:')) continue;

    if (l.includes('facebook.com') || l.includes('instagram.com') || l.includes('linkedin.com')) {
      socials.push(l);
      continue;
    }

    if (!base_url) continue;

    try {
      const urlObj = new URL(l, base_url);
      if (urlObj.hostname === new URL(base_url).hostname) {
        links.push(urlObj.href);
      }
    } catch(e) {}
  }

  const uniqueLinks = [...new Set(links)];
  const interesting = uniqueLinks.filter(l => {
    const lower = l.toLowerCase();
    return keywords.some(k => lower.includes(k));
  }).slice(0, 12);

  if (interesting.length === 0 || !base_url) {
    out.push({
      json: {
        hotel_id: hotel.hotel_id,
        url_to_fetch: base_url,
        homepage_emails: homepageEmails,
        social_links: [...new Set(socials)],
        base_url: base_url
      }
    });
  } else {
    for (const link of interesting) {
      out.push({
        json: {
          hotel_id: hotel.hotel_id,
          url_to_fetch: link,
          homepage_emails: homepageEmails,
          social_links: [...new Set(socials)],
          base_url: base_url
        }
      });
    }
  }
}
return out;

const subpages = $input.all();
const linkItems = $('Extract Links & Socials').all();
const hotels = $('Limit Batch').all();

const hotelMap = {};
for (const h of hotels) {
  hotelMap[h.json.hotel_id] = {
    hotel: h.json,
    emailsMap: {},
    socials: []
  };
}

const emailRegex = /([a-zA-Z0-9._-]+(?:@|\(at\)|\[at\]|&#64;|&amp;#64;|\{at\})[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/gi;
const invalidEnds = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.pdf', '.css', '.js'];
const invalidStarts = ['example@', 'noreply@', 'no-reply@', 'wordpress@', 'sentry@', 'wix@', 'cloudflare@', 'name@'];

function cleanEmail(e) {
  return e.toLowerCase().replace(/\(at\)/g, '@').replace(/\[at\]/g, '@').replace(/&#64;/g, '@').replace(/&amp;#64;/g, '@').replace(/\{at\}/g, '@').replace(/\s+/g, '');
}

function isValidEmail(email) {
  if (invalidEnds.some(ext => email.endsWith(ext))) return false;
  if (invalidStarts.some(start => email.startsWith(start))) return false;
  // Filter software package/version patterns like jquery@3.7.1, slick-carousel@1.8.1, pdfjs-dist@4.2.67
  if (/@\d+\.\d+/.test(email)) return false;
  // Filter common library names or npm package patterns
  if (email.startsWith('jquery@') || email.startsWith('slick-carousel@') || email.startsWith('pdfjs-dist@') || email.startsWith('bootstrap@') || email.startsWith('font-awesome@')) return false;
  // Require valid TLD (at least 2 letters)
  const parts = email.split('@');
  if (parts.length !== 2) return false;
  const domainParts = parts[1].split('.');
  if (domainParts.length < 2) return false;
  const tld = domainParts[domainParts.length - 1];
  if (!/^[a-z]{2,10}$/.test(tld)) return false;
  return true;
}

function getPriorityAndType(email) {
  let type = 'UNKNOWN';
  let priority = 8;
  if (email.includes('job') || email.includes('karriere') || email.includes('career') || email.includes('bewerb') || email.includes('talent')) { type = 'JOBS'; priority = 1; }
  else if (email.includes('hr@') || email.includes('humanresources') || email.includes('personal') || email.includes('recruiting')) { type = 'HR'; priority = 2; }
  else if (email.includes('chef@') || email.includes('kueche') || email.includes('küche') || email.includes('kitchen') || email.includes('gastronomie') || email.includes('fnb') || email.includes('foodandbeverage') || email.includes('fb@') || email.includes('culinary') || email.includes('restaurant') || email.includes('cuisine')) { type = 'KITCHEN_FNB'; priority = 3; }
  else if (email.includes('direktion') || email.includes('director') || email.includes('manager') || email.includes('management') || email.includes('geschäftsleitung') || email.includes('office') || email.includes('administration')) { type = 'MANAGEMENT'; priority = 4; }
  else if (email.includes('info@') || email.includes('kontakt') || email.includes('contact') || email.includes('general')) { type = 'GENERAL'; priority = 5; }
  else if (email.includes('reception') || email.includes('frontoffice') || email.includes('frontdesk')) { type = 'RECEPTION'; priority = 6; }
  else if (email.includes('reservation') || email.includes('booking') || email.includes('reservierung')) { type = 'RESERVATION'; priority = 7; }

  return { type, priority };
}

for (let i = 0; i < linkItems.length; i++) {
  const meta = linkItems[i].json;
  const html = subpages[i]?.json?.data || '';
  const hotel_id = meta.hotel_id;

  let title = 'Homepage';
  const titleMatch = html.match(/<title>([^<]+)<\/title>/i);
  if (titleMatch) title = titleMatch[1].trim().substring(0, 50);

  if (!hotelMap[hotel_id]) continue;
  const map = hotelMap[hotel_id].emailsMap;
  hotelMap[hotel_id].socials = meta.social_links || [];

  let source_type = meta.base_url ? 'WEBSITE' : 'GOOGLE_MAPS';
  let url_source = meta.url_to_fetch || meta.base_url || 'Google Maps';

  const addEmail = (rawE, srcUrl, srcType, pTitle) => {
    const e = cleanEmail(rawE);
    if (!isValidEmail(e)) return;
    const { type, priority } = getPriorityAndType(e);

    if (map[e]) {
      const existing = map[e];
      if (priority < existing.priority) {
        map[e] = { source_url: srcUrl, source_type: srcType, page_title: pTitle, email_type: type, priority: priority };
      }
    } else {
      map[e] = { source_url: srcUrl, source_type: srcType, page_title: pTitle, email_type: type, priority: priority };
    }
  };

  for (const e of (meta.homepage_emails || [])) {
    addEmail(e, meta.base_url || 'Google Maps', source_type, 'Homepage');
  }

  const subEmails = html.match(emailRegex) || [];
  for (const e of subEmails) {
    addEmail(e, url_source, source_type, title);
  }
}

return Object.values(hotelMap).map(h => ({ json: h }));

const aggregated = $('Aggregate Emails').all();
const existingContacts = $('Read Existing Contacts').all().map(i => i.json);

const existingSet = new Set();
for (const c of existingContacts) {
  if (c.hotel_id && c.email) {
    existingSet.add(c.hotel_id + '_' + c.email.toLowerCase());
  }
}

const out = [];
const metrics = {
  date: new Date().toISOString().split('T')[0],
  processed: aggregated.length,
  with_web: 0,
  without_web: 0,
  found: 0,
  hr_found: 0,
  kitchen_fnb_found: 0,
  general_found: 0,
  google_maps_found: 0,
  duplicates_eliminated: 0,
  hotels_with_email: 0
};

for (const item of aggregated) {
  const h = item.json;
  const hid = h.hotel.hotel_id;

  if (h.hotel.website) metrics.with_web++;
  else metrics.without_web++;

  let addedForThisHotel = 0;

  for (const [email, meta] of Object.entries(h.emailsMap)) {
    const key = hid + '_' + email;
    if (existingSet.has(key)) {
      metrics.duplicates_eliminated++;
      continue;
    }

    out.push({
      json: {
        _route: 'contact',
        contact_id: 'cnt-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6),
        hotel_id: hid,
        email: email,
        email_type: meta.email_type,
        priority: meta.priority,
        source_url: meta.source_url,
        page_title: meta.page_title,
        source_type: meta.source_type,
        source_text: h.socials.join(', '),
        confidence: meta.priority <= 2 ? 0.9 : (meta.priority === 3 ? 0.8 : 0.5),
        verified_syntax: true,
        verified_domain: true,
        preferred: false,
        review_status: 'NEEDS_REVIEW',
        created_at: new Date().toISOString()
      }
    });

    addedForThisHotel++;
    metrics.found++;
    if (meta.email_type === 'HR' || meta.email_type === 'JOBS') metrics.hr_found++;
    if (meta.email_type === 'KITCHEN_FNB') metrics.kitchen_fnb_found++;
    if (meta.email_type === 'GENERAL') metrics.general_found++;
    if (meta.source_type === 'GOOGLE_MAPS') metrics.google_maps_found++;
  }

  if (addedForThisHotel > 0) metrics.hotels_with_email++;

  out.push({
    json: {
      _route: 'hotel',
      hotel_id: hid,
      status: 'SCRAPED',
      updated_at: new Date().toISOString()
    }
  });
}

out.push({
  json: {
    _route: 'metric',
    date: metrics.date,
    processed: metrics.processed,
    with_web: metrics.with_web,
    without_web: metrics.without_web,
    found: metrics.found,
    hr_found: metrics.hr_found,
    kitchen_fnb_found: metrics.kitchen_fnb_found,
    general_found: metrics.general_found,
    google_maps_found: metrics.google_maps_found,
    duplicates_eliminated: metrics.duplicates_eliminated,
    hotels_with_email: metrics.hotels_with_email
  }
});

return out;
